CREATE DATABASE IF NOT EXISTS placement_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE placement_db;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,role ENUM('student','company','admin') DEFAULT 'student',status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE students(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT UNIQUE NOT NULL,phone VARCHAR(30),college VARCHAR(180),degree VARCHAR(100),branch VARCHAR(100),graduation_year YEAR NULL,cgpa DECIMAL(4,2),skills TEXT,resume_url VARCHAR(500),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE companies(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT UNIQUE NOT NULL,company_name VARCHAR(180) NOT NULL,industry VARCHAR(120),location VARCHAR(180),website VARCHAR(255),description TEXT,verification_status ENUM('pending','approved','rejected') DEFAULT 'approved',FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE jobs(id INT AUTO_INCREMENT PRIMARY KEY,company_id INT NOT NULL,title VARCHAR(180) NOT NULL,description TEXT NOT NULL,job_type ENUM('Internship','Full Time','Part Time') NOT NULL,location VARCHAR(180),salary VARCHAR(100),min_cgpa DECIMAL(4,2) DEFAULT 0,skills_required TEXT,deadline DATE,status ENUM('open','closed') DEFAULT 'open',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE);
CREATE TABLE applications(id INT AUTO_INCREMENT PRIMARY KEY,job_id INT NOT NULL,student_id INT NOT NULL,status ENUM('Applied','Shortlisted','Interview','Selected','Rejected') DEFAULT 'Applied',applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY unique_application(job_id,student_id),FOREIGN KEY(job_id) REFERENCES jobs(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
